pred_cypher:
MATCH (c:Country)
WHERE EXISTS {
  MATCH (l:Lake)-[:locatedIn]->(c)
  WHERE l.name = "FDR Lake" OR "FDR Lake" IN l.aliases
}
AND EXISTS {
  MATCH (r:River)-[:partOf]->(b:DrainageBasin)-[:locatedIn]->(c)
  WHERE r.name = "Ogeechee River"
}
RETURN DISTINCT c.name, c.area_km2

MATCH (c:Country)-[:locatedIn]->(:Continent)
WHERE EXISTS {
  MATCH (b:DrainageBasin {name: "Nottaway River basin"})-[:locatedIn]->(c)
}
AND EXISTS {
  MATCH (l:Lake {name: "Selwyn Lake"})-[:locatedIn]->(c)
}
RETURN DISTINCT c.name, c.capital
